create or replace function public.claim_notification_batch(p_limit integer default 25) returns setof public.notification_outbox language plpgsql security definer set search_path=public as $$begin if current_user not in('postgres','service_role') then raise exception 'trusted_server_only';end if;return query with picked as(select id from public.notification_outbox where status='queued' and available_at<=now() and attempts<max_attempts order by available_at,created_at for update skip locked limit greatest(1,least(p_limit,100))) update public.notification_outbox o set status='processing',attempts=o.attempts+1,updated_at=now() from picked where o.id=picked.id returning o.*;end$$;revoke all on function public.claim_notification_batch(integer) from public,anon,authenticated;grant execute on function public.claim_notification_batch(integer) to service_role;
create or replace function public.complete_notification_delivery(p_outbox uuid,p_provider text,p_message_id text default null) returns void language plpgsql security definer set search_path=public as $$declare o public.notification_outbox;begin if current_user not in('postgres','service_role') then raise exception 'trusted_server_only';end if;select * into o from public.notification_outbox where id=p_outbox for update;if not found then raise exception 'outbox_not_found';end if;if o.status='sent' then return;end if;update public.notification_outbox set status='sent',provider_key=p_provider,provider_message_id=p_message_id,last_error=null,sent_at=now(),updated_at=now() where id=p_outbox;insert into public.notification_delivery_attempts(tenant_id,outbox_id,provider_key,attempt_no,status,provider_message_id) values(o.tenant_id,o.id,p_provider,o.attempts,'sent',p_message_id);end$$;revoke all on function public.complete_notification_delivery(uuid,text,text) from public,anon,authenticated;grant execute on function public.complete_notification_delivery(uuid,text,text) to service_role;
create or replace function public.fail_notification_delivery(p_outbox uuid,p_provider text,p_error text,p_retryable boolean default true) returns void language plpgsql security definer set search_path=public as $$declare o public.notification_outbox;delay_seconds integer;begin if current_user not in('postgres','service_role') then raise exception 'trusted_server_only';end if;select * into o from public.notification_outbox where id=p_outbox for update;if not found then raise exception 'outbox_not_found';end if;delay_seconds:=least(3600,30*power(2,greatest(o.attempts-1,0))::integer);update public.notification_outbox set status=case when p_retryable and attempts<max_attempts then 'queued' else 'failed' end,provider_key=p_provider,last_error=left(coalesce(p_error,'delivery_failed'),500),available_at=case when p_retryable and attempts<max_attempts then now()+make_interval(secs=>delay_seconds) else available_at end,updated_at=now() where id=p_outbox;insert into public.notification_delivery_attempts(tenant_id,outbox_id,provider_key,attempt_no,status,error_message) values(o.tenant_id,o.id,p_provider,o.attempts,case when p_retryable and o.attempts<o.max_attempts then 'retry_scheduled' else 'failed' end,left(coalesce(p_error,'delivery_failed'),500));end$$;revoke all on function public.fail_notification_delivery(uuid,text,text,boolean) from public,anon,authenticated;grant execute on function public.fail_notification_delivery(uuid,text,text,boolean) to service_role;
